; VM-owned String construction, storage ABI3 with compact strings disabled.
; String payload16: UTF16 char[] reference0, hash8D, hashComputed12D.
; This is a source-checked runtime intrinsic, not execution of original Java Code.
; Uninitialized receivers cannot escape generated bytecode's verifier rules.
option casemap:none
EXTERN boom_object_new:PROC
EXTERN boom_heap_alloc:PROC
PUBLIC boom_string_new
PUBLIC boom_string_construct_chars
PUBLIC boom_string_construct_chars_all
.code
; (heap RCX, oop RDX) -> owned complete live block. No speculative tag reads.
string_ctor_owned PROC
    mov rax,QWORD PTR [rcx+16]
    lea r10,[rcx+128]
    add rax,r10
    jc string_ctor_owned_no
    cmp rax,QWORD PTR [rcx+24]
    jne string_ctor_owned_no
    lea r10,[rcx+160]
    cmp rdx,r10
    jb string_ctor_owned_no
    cmp rdx,rax
    ja string_ctor_owned_no
    test dl,15
    jnz string_ctor_owned_no
    mov r10d,DWORD PTR [rdx-24]
    and r10d,0FFFFFFFDh
    cmp r10d,0B00B0001h
    jne string_ctor_owned_no
    mov r10,QWORD PTR [rdx-32]
    cmp r10,32
    jb string_ctor_owned_no
    test r10b,15
    jnz string_ctor_owned_no
    sub r10,32
    cmp QWORD PTR [rdx-16],r10
    ja string_ctor_owned_no
    add r10,rdx
    jc string_ctor_owned_no
    cmp r10,rax
    ja string_ctor_owned_no
    mov eax,1
    ret
string_ctor_owned_no:
    xor eax,eax
    ret
string_ctor_owned ENDP
; StringPool3 RDX -> heap RAX or zero. Preserves RCX,RDX,R8,R9.
string_ctor_pool PROC
    test rdx,rdx
    jz string_ctor_pool_no
    cmp DWORD PTR [rdx],053545250h
    jne string_ctor_pool_no
    cmp DWORD PTR [rdx+4],3
    jne string_ctor_pool_no
    mov r10,QWORD PTR [rdx+40]
    test r10,r10
    jz string_ctor_pool_no
    cmp DWORD PTR [r10],04F424A43h
    jne string_ctor_pool_no
    cmp DWORD PTR [r10+4],1
    jne string_ctor_pool_no
    cmp QWORD PTR [r10+8],16
    jne string_ctor_pool_no
    cmp DWORD PTR [r10+16],1
    jne string_ctor_pool_no
    cmp DWORD PTR [r10+20],2
    jne string_ctor_pool_no
    mov rax,QWORD PTR [rdx+48]
    test rax,rax
    jz string_ctor_pool_unbound
    cmp DWORD PTR [rax],048454150h
    jne string_ctor_pool_no
    cmp DWORD PTR [rax+4],1
    jne string_ctor_pool_no
    ret
string_ctor_pool_unbound:
    xor eax,eax
    ret
string_ctor_pool_no:
    xor r10d,r10d
    xor eax,eax
    ret
string_ctor_pool ENDP
; (Context32 RCX,StringPool3 RDX,heap R8) -> fresh uninitialized String / NULL.
; Bind the immutable image heap even before any literal/exception was loaded.
boom_string_new PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    sub rsp,32
    .allocstack 32
    .endprolog
    mov rbx,rcx
    mov rsi,r8
    mov rdi,rdx
    test rbx,rbx
    jz string_ctor_new_zero
    cmp DWORD PTR [rbx],0
    jne string_ctor_new_zero
    test rsi,rsi
    jz string_ctor_new_bad
    cmp DWORD PTR [rsi],048454150h
    jne string_ctor_new_bad
    cmp DWORD PTR [rsi+4],1
    jne string_ctor_new_bad
    call string_ctor_pool
    test rax,rax
    jnz string_ctor_new_bound
    test r10,r10
    jz string_ctor_new_bad
    lock cmpxchg QWORD PTR [rdi+48],rsi
    test rax,rax
    jz string_ctor_new_ready
string_ctor_new_bound:
    cmp rax,rsi
    jne string_ctor_new_bad
string_ctor_new_ready:
    mov rcx,rsi
    mov rdx,QWORD PTR [rdi+40]
    mov r8,rbx
    call boom_object_new
    jmp string_ctor_new_done
string_ctor_new_bad:
    mov DWORD PTR [rbx],7
string_ctor_new_zero:
    xor eax,eax
string_ctor_new_done:
    add rsp,32
    pop rdi
    pop rsi
    pop rbx
    ret
boom_string_new ENDP
; (Context32 RCX,argv{receiver,char[],offset,count} RDX,StringPool3 R8).
; Source char[] null is checked before signed bounds; copy never aliases input.
boom_string_construct_chars PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    push r12
    .pushreg r12
    push r13
    .pushreg r13
    push r14
    .pushreg r14
    push r15
    .pushreg r15
    sub rsp,32
    .allocstack 32
    .endprolog
    mov rbx,rcx
    mov rsi,rdx
    mov rdi,r8
    test rbx,rbx
    jz string_ctor_zero
    cmp DWORD PTR [rbx],0
    jne string_ctor_zero
    test rsi,rsi
    jz string_ctor_bad
    mov rdx,rdi
    call string_ctor_pool
    test rax,rax
    jz string_ctor_bad
    mov r12,rax
    mov r13,QWORD PTR [rsi]
    test r13,r13
    jz string_ctor_null
    mov rcx,r12
    mov rdx,r13
    call string_ctor_owned
    test eax,eax
    jz string_ctor_bad
    mov rax,QWORD PTR [rdi+40]
    cmp QWORD PTR [r13-8],rax
    jne string_ctor_bad
    cmp QWORD PTR [r13-16],16
    jne string_ctor_bad
    cmp DWORD PTR [r13-20],1
    jne string_ctor_bad
    cmp QWORD PTR [r13],0
    jne string_ctor_bad
    mov r14,QWORD PTR [rsi+8]
    test r14,r14
    jz string_ctor_null
    mov rcx,r12
    mov rdx,r14
    call string_ctor_owned
    test eax,eax
    jz string_ctor_bad
    cmp QWORD PTR [r14-8],261
    jne string_ctor_bad
    cmp DWORD PTR [r14-20],0
    jne string_ctor_bad
    mov rax,QWORD PTR [r14-16]
    test al,1
    jnz string_ctor_bad
    shr rax,1
    movsxd rdx,DWORD PTR [rsi+16]
    test rdx,rdx
    js string_ctor_bounds
    movsxd r15,DWORD PTR [rsi+24]
    test r15,r15
    js string_ctor_bounds
    cmp rdx,rax
    ja string_ctor_bounds
    sub rax,rdx
    cmp r15,rax
    ja string_ctor_bounds
    lea r14,[r14+rdx*2]
    mov rcx,r12
    lea rdx,[r15*2]
    xor r8d,r8d
    mov r9d,261
    call boom_heap_alloc
    test rax,rax
    jz string_ctor_oom
    mov rdi,rax
    mov rsi,r14
    mov rcx,r15
    rep movsw
    mov QWORD PTR [r13],rax
    mov QWORD PTR [r13+8],0
    jmp string_ctor_zero
string_ctor_null:
    mov DWORD PTR [rbx],4
    jmp string_ctor_zero
string_ctor_bounds:
    mov DWORD PTR [rbx],11
    jmp string_ctor_zero
string_ctor_oom:
    mov DWORD PTR [rbx],3
    jmp string_ctor_zero
string_ctor_bad:
    mov DWORD PTR [rbx],7
string_ctor_zero:
    xor eax,eax
    add rsp,32
    pop r15
    pop r14
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret
boom_string_construct_chars ENDP
; (Context32,argv{uninitialized String,char[]},StringPool3).
; The original one-argument constructor evaluates input.length before delegation.
boom_string_construct_chars_all PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    sub rsp,64
    .allocstack 64
    .endprolog
    mov rbx,rcx
    mov rsi,rdx
    mov rdi,r8
    test rbx,rbx
    jz string_ctor_all_done
    cmp DWORD PTR [rbx],0
    jne string_ctor_all_done
    test rsi,rsi
    jz string_ctor_all_bad
    mov rdx,rdi
    call string_ctor_pool
    test rax,rax
    jz string_ctor_all_bad
    mov rdx,QWORD PTR [rsi+8]
    test rdx,rdx
    jz string_ctor_all_null
    mov rcx,rax
    call string_ctor_owned
    test eax,eax
    jz string_ctor_all_bad
    mov rdx,QWORD PTR [rsi+8]
    cmp QWORD PTR [rdx-8],261
    jne string_ctor_all_bad
    cmp DWORD PTR [rdx-20],0
    jne string_ctor_all_bad
    mov rax,QWORD PTR [rdx-16]
    test al,1
    jnz string_ctor_all_bad
    shr rax,1
    cmp rax,07FFFFFFFh
    ja string_ctor_all_bad
    mov QWORD PTR [rsp+56],rax
    mov QWORD PTR [rsp+40],rdx
    mov rax,QWORD PTR [rsi]
    mov QWORD PTR [rsp+32],rax
    mov QWORD PTR [rsp+48],0
    mov rcx,rbx
    lea rdx,[rsp+32]
    mov r8,rdi
    call boom_string_construct_chars
    jmp string_ctor_all_done
string_ctor_all_null:
    mov DWORD PTR [rbx],4
    jmp string_ctor_all_done
string_ctor_all_bad:
    mov DWORD PTR [rbx],7
string_ctor_all_done:
    xor eax,eax
    add rsp,64
    pop rdi
    pop rsi
    pop rbx
    ret
boom_string_construct_chars_all ENDP
END
